contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 shareAmount, uint256 baseMinAmount, uint256 quoteMinAmount, address to, bytes calldata data) public {
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(reverted && tsAfter == tsBefore && balAfter == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 mtFeeRate) public payable {
        require(true);
        uint256 before = c._MT_FEE_RATE_();
        bool reverted;
        c.adjustMtFeeRate(mtFeeRate);
        reverted = false;
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        require(c.totalSupply() == 0);
        bool reverted;
        try c.buyShares(to) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.totalSupply() == 0);
    }
    receive() external payable {}
}
